available_tools:
[
  {
    "name": "files__create_directory",
    "description": "Create a new directory or ensure a directory exists. Can create multiple nested directories in one operation.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "path": {
          "description": "The path to the directory",
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__directory_tree",
    "description": "Get a recursive tree view of files and directories as a JSON structure.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "includeFiles": {
          "default": true,
          "description": "Include files in the output",
          "type": "boolean"
        },
        "maxDepth": {
          "default": 10,
          "description": "Maximum depth to traverse",
          "type": "number"
        },
        "path": {
          "description": "The path to the directory",
          "type": "string"
        },
        "showHidden": {
          "default": false,
          "description": "Show hidden files starting with .",
          "type": "boolean"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__edit_file",
    "description": "Make line-based edits to a text file. Each edit replaces exact line sequences with new content. Returns a git-style diff showing the changes made.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "dryRun": {
          "default": false,
          "description": "Preview changes using git-style diff format",
          "type": "boolean"
        },
        "edits": {
          "description": "Array of edit operations",
          "items": {
            "additionalProperties": false,
            "properties": {
              "newText": {
                "description": "Text to replace with",
                "type": "string"
              },
              "oldText": {
                "description": "Text to search for - must match exactly",
                "type": "string"
              }
            },
            "required": [
              "oldText",
              "newText"
            ],
            "type": "object"
          },
          "type": "array"
        },
        "path": {
          "description": "The path to the file",
          "type": "string"
        }
      },
      "required": [
        "path",
        "edits"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__get_file_info",
    "description": "Retrieve detailed metadata about a file or directory. Returns comprehensive information including size, creation time, last modified time, permissions, and type.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "path": {
          "description": "The path to the file or directory",
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__get_pwd",
    "description": "Returns the current working directory (pwd), which is used as the base for relative paths.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "properties": {},
      "type": "object"
    }
  },
  {
    "name": "files__list_directory",
    "description": "Get a detailed listing of all files and directories in a specified path. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "path": {
          "description": "The path to the directory",
          "type": "string"
        },
        "reverse": {
          "default": false,
          "description": "Reverse the sort order",
          "type": "boolean"
        },
        "showHidden": {
          "default": false,
          "description": "Show hidden files starting with .",
          "type": "boolean"
        },
        "sortBy": {
          "default": "default",
          "description": "Sorting mode: default (directories first), name, or type",
          "enum": [
            "default",
            "name",
            "type"
          ],
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__list_directory_info",
    "description": "Returns information about the filesystem server.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "properties": {},
      "type": "object"
    }
  },
  {
    "name": "files__move_file",
    "description": "Move or rename files and directories. Can move files between directories and rename them in a single operation.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "destination": {
          "description": "The destination file or directory path",
          "type": "string"
        },
        "overwrite": {
          "default": false,
          "description": "Overwrite destination if it exists",
          "type": "boolean"
        },
        "source": {
          "description": "The source file or directory path",
          "type": "string"
        }
      },
      "required": [
        "source",
        "destination"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__read_binary_file",
    "description": "Read a binary file and return its contents as base64 encoded string.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "path": {
          "description": "The path to the binary file",
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__read_file",
    "description": "Read the complete contents of a file from the file system. Handles various text encodings and provides detailed error messages if the file cannot be read.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "encoding": {
          "default": "utf-8",
          "description": "File encoding (default: utf-8)",
          "type": "string"
        },
        "endLine": {
          "description": "Ending line number (1-indexed) for reading a specific range",
          "type": "number"
        },
        "maxSize": {
          "description": "Maximum file size in bytes to read (default: no limit)",
          "type": "number"
        },
        "path": {
          "description": "The path to the file",
          "type": "string"
        },
        "startLine": {
          "description": "Starting line number (1-indexed) for reading a specific range",
          "type": "number"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__read_multiple_files",
    "description": "Read the contents of multiple files in one call. Provide a list of file paths to read, and optionally specify an encoding, whether to include file metadata, whether to ignore read errors, and a separator string between file contents.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "encoding": {
          "default": "utf-8",
          "description": "File encoding (default: utf-8)",
          "type": "string"
        },
        "ignoreErrors": {
          "default": false,
          "description": "Silently skip files that cannot be read instead of including error messages",
          "type": "boolean"
        },
        "includeMetadata": {
          "default": false,
          "description": "Prepend file metadata (size, last modified) before each file's content",
          "type": "boolean"
        },
        "paths": {
          "description": "Array of file paths to read",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "separator": {
          "default": "---",
          "description": "Separator string inserted between file contents (default: '---')",
          "type": "string"
        }
      },
      "required": [
        "paths"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__search_files",
    "description": "Recursively search for files and directories matching a pattern. Searches through all subdirectories from the starting path.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "excludePatterns": {
          "default": [],
          "description": "Patterns to exclude from search",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "maxDepth": {
          "default": 20,
          "description": "Maximum depth to search",
          "type": "number"
        },
        "maxResults": {
          "default": 1000,
          "description": "Maximum number of results to return",
          "type": "number"
        },
        "path": {
          "description": "The starting directory path",
          "type": "string"
        },
        "pattern": {
          "description": "The search pattern",
          "type": "string"
        },
        "searchContents": {
          "default": false,
          "description": "Search file contents instead of just names",
          "type": "boolean"
        }
      },
      "required": [
        "path",
        "pattern"
      ],
      "type": "object"
    }
  },
  {
    "name": "files__write_file",
    "description": "Create a new file or completely overwrite an existing file with new content. Use with caution as it will overwrite existing files without warning.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "content": {
          "description": "The content to write to the file",
          "type": "string"
        },
        "createDirectories": {
          "default": false,
          "description": "Create parent directories if they don't exist",
          "type": "boolean"
        },
        "path": {
          "description": "The path to the file",
          "type": "string"
        }
      },
      "required": [
        "path",
        "content"
      ],
      "type": "object"
    }
  },
  {
    "name": "tasks__tasks_add",
    "description": "Add new tasks with a specific status. It's faster and cheaper if you use this in batch. User can add atomically while AI works using the CLI add tool",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "index": {
          "description": "0-based index to place the tasks. e.g.:\n- 0 for \"Do this next\"\n- Omit to place at the end (\"Do this later\")",
          "minimum": 0,
          "type": "integer"
        },
        "source_id": {
          "description": "Source ID from task_setup() response\n- Defaults to most recent in the workspace if not provided\n- Try to always provide it!\n- If you don't have it, ask the user for a file path and call task_setup()",
          "minLength": 1,
          "type": "string"
        },
        "status": {
          "description": "You might need to infer it from the context:\n- \"To Do\" for tasks coming up next (e.g. \"Do X next\")\n- \"In Progress\" for what you'll do now (e.g. \"First do X\")\n- \"Reminders\" instructions for you (the AI) to be constantly reminded of\n- \"Notes\" to collect non-actionable notes",
          "enum": [
            "In Progress",
            "To Do",
            "Backlog",
            "Done",
            "Reminders",
            "Notes",
            "Deleted"
          ],
          "type": "string"
        },
        "texts": {
          "description": "Each text becomes a task",
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "type": "array"
        }
      },
      "required": [
        "texts",
        "status"
      ],
      "type": "object"
    }
  },
  {
    "name": "tasks__tasks_search",
    "description": "Search tasks by status, text terms, or task IDs. You can optionally filter by one or more statuses, search terms, and/or IDs, and limit the number of results. If source_id is not provided, the most recent source in the workspace is used by default.",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "ids": {
          "description": "A list of specific task IDs to retrieve. Optional",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "limit": {
          "description": "Cap on the number of results returned. Intended for use with very large task lists",
          "minimum": 1,
          "type": "integer"
        },
        "source_id": {
          "description": "Source ID returned by task_setup()\n- Falls back to the most recently used source in the workspace if omitted\n- Provide this whenever possible\n- If unavailable, ask the user for a file path and call task_setup() to obtain it",
          "minLength": 1,
          "type": "string"
        },
        "statuses": {
          "description": "One or more statuses to filter by. Returns tasks from all statuses if not specified",
          "items": {
            "description": "You might need to infer it from the context:\n- \"To Do\" for tasks coming up next (e.g. \"Do X next\")\n- \"In Progress\" for what you'll do now (e.g. \"First do X\")\n- \"Reminders\" instructions for you (the AI) to be constantly reminded of\n- \"Notes\" to collect non-actionable notes",
            "enum": [
              "In Progress",
              "To Do",
              "Backlog",
              "Done",
              "Reminders",
              "Notes",
              "Deleted"
            ],
            "type": "string"
          },
          "type": "array"
        },
        "terms": {
          "description": "Text terms to filter tasks by content or status. Matching is case-insensitive and uses OR logic. Regex and wildcards are not supported",
          "items": {
            "type": "string"
          },
          "type": "array"
        }
      },
      "type": "object"
    }
  },
  {
    "name": "tasks__tasks_setup",
    "description": "Initializes a source file from a path.\n- Always call this once per conversation when asked to use these tools\n- If the file path is not provided, ask the user to clarify it before calling this tool\n- Creates the file if it does not already exist\n- Returns the source ID for subsequent use\n- Use mcp-tasks tools when the user mentions new or updated tasks",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "source_path": {
          "minLength": 1,
          "type": "string"
        },
        "workspace": {
          "description": "Workspace or project directory path, typically provided by the IDE or set to $PWD",
          "type": "string"
        }
      },
      "required": [
        "source_path"
      ],
      "type": "object"
    }
  },
  {
    "name": "tasks__tasks_summary",
    "description": "Get per-status task counts and the WIP task(s). Redundant right after tasks_add/tasks_update",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "source_id": {
          "description": "Source ID from task_setup() response\n- Defaults to most recent in the workspace if not provided\n- Try to always provide it!\n- If you don't have it, ask the user for a file path and call task_setup()",
          "minLength": 1,
          "type": "string"
        }
      },
      "type": "object"
    }
  },
  {
    "name": "tasks__tasks_update",
    "description": "Update tasks in bulk by ID to a different status. Returns complete summary no need to call tasks_summary afterwards. Prevents AI accidentally rename or deleting tasks during mass updates, not even possible",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "additionalProperties": false,
      "properties": {
        "ids": {
          "description": "The IDs of existing tasks",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "index": {
          "description": "0-based index to place the tasks. e.g.:\n- 0 for \"Do this next\"\n- Omit to place at the end (\"Do this later\")",
          "minimum": 0,
          "type": "integer"
        },
        "source_id": {
          "description": "Source ID from task_setup() response\n- Defaults to most recent in the workspace if not provided\n- Try to always provide it!\n- If you don't have it, ask the user for a file path and call task_setup()",
          "minLength": 1,
          "type": "string"
        },
        "status": {
          "anyOf": [
            {
              "description": "You might need to infer it from the context:\n- \"To Do\" for tasks coming up next (e.g. \"Do X next\")\n- \"In Progress\" for what you'll do now (e.g. \"First do X\")\n- \"Reminders\" instructions for you (the AI) to be constantly reminded of\n- \"Notes\" to collect non-actionable notes",
              "enum": [
                "In Progress",
                "To Do",
                "Backlog",
                "Done",
                "Reminders",
                "Notes",
                "Deleted"
              ],
              "type": "string"
            },
            {
              "const": "Deleted",
              "type": "string"
            }
          ],
          "description": "You might need to infer it from the context:\n- \"To Do\" for tasks coming up next (e.g. \"Do X next\")\n- \"In Progress\" for what you'll do now (e.g. \"First do X\")\n- \"Reminders\" instructions for you (the AI) to be constantly reminded of\n- \"Notes\" to collect non-actionable notes\n- \"Deleted\" when they want these removed\n- Updating tasks to In Progress moves others to To Do, finishing a In Progress task moves the first Done to In Progress"
        }
      },
      "required": [
        "ids",
        "status"
      ],
      "type": "object"
    }
  }
]
